INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000023b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy of law at B2","Use Rechtsphilosophie vocabulary","Talk about natural law and positivism"],"explanation":{"intro":"Philosophy of law vocabulary covers natural law, legal positivism, and the legitimacy of law at B2.","culturalNote":"Rechtsphilosophie: two major traditions: Naturrecht (natural law — law grounded in nature/reason/morality, higher than positive law — Cicero, Aquinas, Locke, Kant) vs. Rechtspositivismus (legal positivism — law is whatever the sovereign enacts — Bentham, Austin, Kelsen, Hart). German import: Radbruchsche Formel (Radbruch formula 1946 — positive law loses binding force when grossly unjust, applied at Nuremberg and against DDR judges). Key question: what makes law legitimate?"},"examples":[{"german":"Der Rechtspositivismus trennt scharf zwischen Recht und Moral: Was rechtens ist, wird durch formale Geltung bestimmt, nicht durch moralischen Inhalt.","english":"Legal positivism draws a sharp distinction between law and morality: what is law is determined by formal validity, not by moral content."},{"german":"Die Radbruchsche Formel formuliert eine Grenze des Rechtspositivismus: Wenn positives Recht ein unerträgliches Maß an Ungerechtigkeit erreicht, verliert es seinen Anspruch auf rechtliche Geltung.","english":"The Radbruch formula formulates a limit of legal positivism: when positive law reaches an intolerable degree of injustice, it loses its claim to legal validity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss legal philosophy, positivism vs. natural law, and the Radbruch formula at B2."}}',
'{"items":[{"word":"scharf trennen","translation":"to draw a sharp distinction","pronunciation":"sharf TREN-en","example":"Scharf zwischen X und Y trennen."},{"word":"die Geltung","translation":"validity/force (of law)","pronunciation":"dee GEL-toong","example":"Formale Geltung."},{"word":"rechtens","translation":"lawful/what is law","pronunciation":"REKH-tens","example":"Was rechtens ist."},{"word":"unerträglich","translation":"intolerable","pronunciation":"oon-er-TRÄKH-likh","example":"Unerträgliches Maß."},{"word":"der Anspruch","translation":"claim","pronunciation":"dayr AN-sproookh","example":"Anspruch auf Geltung."},{"word":"formulieren","translation":"to formulate","pronunciation":"for-moo-LEER-en","example":"Eine Formel formulieren."}]}',
'{"title":"Scharf zwischen X und Y trennen — to draw a sharp distinction between X and Y","pattern":"scharf zwischen X und Y trennen = to draw a sharp (clear) distinction between X and Y (scharf = sharp, emphasising clarity and strictness of the separation)","explanation":"Scharf zwischen X und Y trennen = to draw a sharp distinction between. Der Positivismus trennt scharf zwischen Recht und Moral = Positivism draws a sharp distinction between law and morality. Scharf as adverb (sharply) modifies the strictness of the division. Common in philosophical and analytical discourse. Compare: unterscheiden zwischen (to distinguish between — more neutral), abgrenzen von (to demarcate from — spatial metaphor), unterscheiden von (to differentiate from), eine Grenze ziehen zwischen (to draw a line between — more deliberate act).","examples":[{"sentence":"Man muss scharf zwischen Ursache und Wirkung trennen.","translation":"One must draw a sharp distinction between cause and effect."},{"sentence":"Die Wissenschaft versucht, scharf zwischen Fakten und Wertungen zu trennen.","translation":"Science tries to draw a sharp distinction between facts and value judgements."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unerträglich'' means?","options":["intolerable","unbearable","unacceptable","impossible"],"correctAnswer":"intolerable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Legal positivism draws a sharp distinction between law and morality: what is law is determined by formal validity, not by moral content.","options":["Der Rechtspositivismus trennt scharf zwischen Recht und Moral: Was rechtens ist, wird durch formale Geltung bestimmt, nicht durch moralischen Inhalt.","Für den Rechtspositivismus ist Recht und Moral streng getrennt.","Was legal ist, hängt von formalen Regeln ab, nicht von Moral.","Der Rechtspositivismus definiert Recht ohne moralische Bewertung."],"correctAnswer":"Der Rechtspositivismus trennt scharf zwischen Recht und Moral: Was rechtens ist, wird durch formale Geltung bestimmt, nicht durch moralischen Inhalt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Man muss scharf zwischen Ursache und Wirkung ___.","options":["trennen","unterscheiden","abgrenzen","scheiden"],"correctAnswer":"trennen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Science tries to draw a sharp distinction between facts and value judgements","wordBankItems":["Die","Wissenschaft","versucht",",","scharf","zwischen","Fakten","und","Wertungen","zu","trennen","."],"correctAnswer":"Die Wissenschaft versucht , scharf zwischen Fakten und Wertungen zu trennen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Geltung'' means?","options":["validity/force","validity","binding force","authority"],"correctAnswer":"validity/force"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000023c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss political philosophy at B2","Use politische Philosophie vocabulary","Talk about justice, liberty, and social contract"],"explanation":{"intro":"Political philosophy vocabulary covers key concepts of justice, liberty, the state, and social contract theory at B2.","culturalNote":"Politische Philosophie: key German/European tradition. Social contract: Hobbes (Leviathan — state vs. state of nature), Locke (natural rights, consent), Rousseau (Volonté générale — general will), Kant (republican constitution, moral law). Liberal tradition: Mill (Harm Principle — Schadensprinzip), Rawls (Schleier des Unwissens — veil of ignorance, principles of justice). Communitarian critique: MacIntyre, Sandel (Grenzen des Liberalismus). Habermas (Diskursethik — discourse ethics, deliberative democracy)."},"examples":[{"german":"John Rawls argumentierte, dass gerechte gesellschaftliche Grundstrukturen diejenigen sind, auf die vernünftige Menschen sich hinter einem ''Schleier des Unwissens'' einigen würden.","english":"John Rawls argued that just basic social structures are those on which reasonable people would agree behind a ''veil of ignorance''."},{"german":"Der Liberalismus beruht auf der Prämisse, dass der Staat neutral gegenüber konkurrierenden Vorstellungen des Guten bleiben sollte, sofern diese das Schadensprinzip nicht verletzen.","english":"Liberalism rests on the premise that the state should remain neutral towards competing conceptions of the good, insofar as these do not violate the harm principle."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss political philosophy, social contract theory, Rawls, and liberalism at B2."}}',
'{"items":[{"word":"argumentieren","translation":"to argue (academically)","pronunciation":"ar-goo-men-TEER-en","example":"Theoretisch argumentieren."},{"word":"die Grundstruktur","translation":"basic structure","pronunciation":"dee GROOND-shtrooktoor","example":"Gesellschaftliche Grundstrukturen."},{"word":"der Schleier des Unwissens","translation":"veil of ignorance","pronunciation":"dayr SHLY-er des OON-vi-sens","example":"Schleier des Unwissens."},{"word":"neutral bleiben","translation":"to remain neutral","pronunciation":"noy-TRAHL bly-ben","example":"Neutral gegenüber Wertvorstellungen."},{"word":"konkurrierend","translation":"competing","pronunciation":"kon-koo-REER-end","example":"Konkurrierende Vorstellungen."},{"word":"sofern","translation":"insofar as/provided that","pronunciation":"zo-FERN","example":"Sofern sie X nicht verletzen."}]}',
'{"title":"Sofern — insofar as, provided that (conditional with implicit limit)","pattern":"sofern + clause = insofar as, provided that (marks a conditional limit — the main clause is valid only when the sofern-clause is satisfied)","explanation":"Sofern = insofar as, provided that (conditional — the main clause holds only if the sofern-condition is met). Der Staat bleibt neutral, sofern das Schadensprinzip nicht verletzt wird = The state remains neutral, provided the harm principle is not violated. Subordinating conjunction — verb goes to end. Compare: soweit (as far as — also limits scope, but scope-based rather than conditional), solange (as long as — temporal condition), vorausgesetzt dass (provided that — more explicit), falls (if — more neutral conditional without the limiting nuance).","examples":[{"sentence":"Die Regelung gilt, sofern keine Ausnahmen vereinbart wurden.","translation":"The regulation applies, provided no exceptions were agreed."},{"sentence":"Demonstrationen sind erlaubt, sofern sie friedlich verlaufen.","translation":"Demonstrations are permitted, provided they proceed peacefully."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Konkurrierend'' means?","options":["competing","rival","opposing","conflicting"],"correctAnswer":"competing"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"John Rawls argued that just basic social structures are those on which reasonable people would agree behind a ''veil of ignorance''.","options":["John Rawls argumentierte, dass gerechte gesellschaftliche Grundstrukturen diejenigen sind, auf die vernünftige Menschen sich hinter einem ''Schleier des Unwissens'' einigen würden.","Rawls entwickelte ein Modell der Gerechtigkeit, das auf hypothetischer Gleichheit basiert.","Der Schleier des Unwissens ist ein Gedankenexperiment für Gerechtigkeit.","Rawls zufolge sind gerechte Strukturen solche, die wir ohne Wissen über unsere Position wählen würden."],"correctAnswer":"John Rawls argumentierte, dass gerechte gesellschaftliche Grundstrukturen diejenigen sind, auf die vernünftige Menschen sich hinter einem ''Schleier des Unwissens'' einigen würden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Demonstrationen sind erlaubt, sofern sie friedlich ___.","options":["verlaufen","bleiben","stattfinden","vorgehen"],"correctAnswer":"verlaufen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The regulation applies provided no exceptions were agreed","wordBankItems":["Die","Regelung","gilt",",","sofern","keine","Ausnahmen","vereinbart","wurden","."],"correctAnswer":"Die Regelung gilt , sofern keine Ausnahmen vereinbart wurden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Argumentieren'' means?","options":["to argue (academically)","to claim","to maintain","to assert"],"correctAnswer":"to argue (academically)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000023d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss ethics at B2","Use Ethik vocabulary","Talk about major ethical theories"],"explanation":{"intro":"Ethics vocabulary covers major ethical traditions — deontology, consequentialism, virtue ethics — at B2.","culturalNote":"Ethik: three main traditions: 1) Deontologie (deontology — Kant, categorical imperative: Kategorischer Imperativ — act only according to a maxim you could will to be universal law); 2) Konsequentialismus/Utilitarismus (consequentialism/utilitarianism — Bentham, Mill: greatest happiness principle); 3) Tugendethik (virtue ethics — Aristotle: eudaimonia, moral character). Applied ethics: Bioethik, Medizinethik, Umweltethik, Wirtschaftsethik. German context: Habermas (Diskursethik — discourse ethics: ethical norms valid only if all affected could agree in rational discourse)."},"examples":[{"german":"Kants kategorischer Imperativ verlangt, nur nach derjenigen Maxime zu handeln, durch die man zugleich wollen kann, dass sie ein allgemeines Gesetz werde.","english":"Kant''s categorical imperative demands to act only according to that maxim through which one can at the same time will that it become a universal law."},{"german":"Im Gegensatz zur deontologischen Ethik bewertet der Utilitarismus Handlungen nicht nach ihrer Absicht, sondern nach ihren Konsequenzen für das Gesamtwohlbefinden.","english":"In contrast to deontological ethics, utilitarianism evaluates actions not by their intention, but by their consequences for overall well-being."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss major ethical theories, Kant''s categorical imperative, and utilitarianism at B2."}}',
'{"items":[{"word":"verlangen","translation":"to demand/require","pronunciation":"fer-LANG-en","example":"Etwas verlangen."},{"word":"die Maxime","translation":"maxim","pronunciation":"dee mak-SEE-meh","example":"Nach einer Maxime handeln."},{"word":"die Absicht","translation":"intention","pronunciation":"dee AP-zikht","example":"Nach der Absicht beurteilen."},{"word":"das Gesamtwohlbefinden","translation":"overall well-being","pronunciation":"dahs geh-ZAHMT-vohl-beh-fin-den","example":"Gesamtwohlbefinden."},{"word":"deontologisch","translation":"deontological","pronunciation":"deh-on-to-LO-gish","example":"Deontologische Ethik."},{"word":"im Gegensatz zu","translation":"in contrast to","pronunciation":"im GAY-gen-zats tsoo","example":"Im Gegensatz zur Deontologie."}]}',
'{"title":"Im Gegensatz zu — in contrast to (introducing a clear opposition between two positions)","pattern":"im Gegensatz zu + dative = in contrast to (introduces a contrasting position; the main clause then describes the alternative)","explanation":"Im Gegensatz zu + dative = in contrast to (strong opposition between two positions). Im Gegensatz zur deontologischen Ethik bewertet der Utilitarismus... = In contrast to deontological ethics, utilitarianism evaluates... Used in analytical/comparative writing. Compare: während (while/whereas — can be temporal or contrastive), anders als (unlike/different from — less formal), entgegen + dative (contrary to — more confrontational, often contradicting expectations), wohingegen (whereas — more explicit contrast clause).","examples":[{"sentence":"Im Gegensatz zu Frankreich hat Deutschland kein ausgeprägtes Zentralisierungsprinzip.","translation":"In contrast to France, Germany does not have a strong centralisation principle."},{"sentence":"Im Gegensatz zu früheren Generationen legt die heutige Jugend mehr Wert auf Work-Life-Balance.","translation":"In contrast to earlier generations, today''s youth places more value on work-life balance."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Absicht'' means?","options":["intention","purpose","motive","aim"],"correctAnswer":"intention"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In contrast to deontological ethics, utilitarianism evaluates actions not by their intention, but by their consequences for overall well-being.","options":["Im Gegensatz zur deontologischen Ethik bewertet der Utilitarismus Handlungen nicht nach ihrer Absicht, sondern nach ihren Konsequenzen für das Gesamtwohlbefinden.","Utilitarismus und Deontologie unterscheiden sich in ihrer Bewertungsgrundlage.","Für den Utilitarismus zählen Konsequenzen, nicht Absichten.","Der Utilitarismus fragt nach den Folgen einer Handlung, nicht nach ihrer Motivation."],"correctAnswer":"Im Gegensatz zur deontologischen Ethik bewertet der Utilitarismus Handlungen nicht nach ihrer Absicht, sondern nach ihren Konsequenzen für das Gesamtwohlbefinden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Im Gegensatz zu Frankreich hat Deutschland kein ausgeprägtes ___.","options":["Zentralisierungsprinzip","Zentralismus","Einheitsmodell","Zentralisierungssystem"],"correctAnswer":"Zentralisierungsprinzip"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In contrast to earlier generations today''s youth places more value on work-life balance","wordBankItems":["Im","Gegensatz","zu","früheren","Generationen","legt","die","heutige","Jugend","mehr","Wert","auf","Work-Life-Balance","."],"correctAnswer":"Im Gegensatz zu früheren Generationen legt die heutige Jugend mehr Wert auf Work-Life-Balance ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verlangen'' means?","options":["to demand/require","to want","to ask for","to require"],"correctAnswer":"to demand/require"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000023e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss epistemology at B2","Use Erkenntnistheorie vocabulary","Talk about knowledge, justification, and truth"],"explanation":{"intro":"Epistemology vocabulary covers theories of knowledge, justification, and the nature of truth at B2.","culturalNote":"Erkenntnistheorie (epistemology): how do we know what we know? Key positions: Rationalismus (rationalism — Descartes, Leibniz: reason is primary source), Empirismus (empiricism — Locke, Hume, Berkeley: experience is primary source), Kants Synthese (transcendental idealism — synthetic a priori knowledge). Key concepts: Rechtfertigung (justification — what makes a belief a knowledge claim), Fallibilismus (fallibilism — Popper: all knowledge provisional and falsifiable), Konstruktivismus (constructivism — knowledge constructed, not found). Key question: Können wir die Außenwelt erkennen? (Can we know the external world?)"},"examples":[{"german":"Erkenntnistheorie befasst sich mit der Frage, unter welchen Bedingungen eine wahre, gerechtfertigte Überzeugung als Wissen gelten kann.","english":"Epistemology deals with the question of under what conditions a true, justified belief can count as knowledge."},{"german":"Poppers Falsifikationismus besagt, dass wissenschaftliche Theorien nie endgültig verifiziert, sondern nur vorläufig durch das Ausbleiben ihrer Widerlegung bestätigt werden können.","english":"Popper''s falsificationism states that scientific theories can never be definitively verified, but only provisionally confirmed through the absence of their refutation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss epistemology, justified belief, and Popper''s falsificationism at B2."}}',
'{"items":[{"word":"sich befassen mit","translation":"to deal with","pronunciation":"zikh beh-FA-sen mit","example":"Sich mit einer Frage befassen."},{"word":"die Überzeugung","translation":"belief/conviction","pronunciation":"dee ü-ber-TSOY-goong","example":"Wahre gerechtfertigte Überzeugung."},{"word":"gerechtfertigt","translation":"justified","pronunciation":"geh-REKHT-fer-tigt","example":"Gerechtfertigte Überzeugung."},{"word":"endgültig","translation":"definitive/final","pronunciation":"ENT-gül-tikh","example":"Endgültig verifizieren."},{"word":"vorläufig","translation":"provisional","pronunciation":"FOR-löy-fikh","example":"Vorläufig bestätigt."},{"word":"das Ausbleiben","translation":"absence/non-occurrence","pronunciation":"dahs OWS-bly-ben","example":"Ausbleiben der Widerlegung."}]}',
'{"title":"Sich befassen mit — to deal with, to occupy oneself with (engage in a topic)","pattern":"sich mit etwas befassen = to deal with, to occupy oneself with (deliberately engage with a topic or question)","explanation":"Sich mit etwas befassen = to deal with, to engage with (reflexive; implies deliberate, sustained engagement, often intellectual or professional). Erkenntnistheorie befasst sich mit der Frage... = Epistemology deals with the question... Perfect: hat sich befasst. Compare: sich beschäftigen mit (to occupy oneself with — more everyday, also professional), behandeln (to deal with/treat — from a subject''s perspective, less reflexive), sich widmen (to devote oneself to — stronger commitment), angehen (to address — more practical/problem-oriented).","examples":[{"sentence":"Die Kommission befasste sich mit den Ursachen der Krise.","translation":"The commission dealt with the causes of the crisis."},{"sentence":"Er befasst sich seit Jahren mit der Geschichte des Mittelalters.","translation":"He has been dealing with the history of the Middle Ages for years."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gerechtfertigt'' means?","options":["justified","warranted","valid","defensible"],"correctAnswer":"justified"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Epistemology deals with the question of under what conditions a true, justified belief can count as knowledge.","options":["Erkenntnistheorie befasst sich mit der Frage, unter welchen Bedingungen eine wahre, gerechtfertigte Überzeugung als Wissen gelten kann.","Erkenntnistheorie untersucht, was Wissen ist.","Unter welchen Bedingungen eine Überzeugung als Wissen gilt, untersucht die Erkenntnistheorie.","Wann ist eine Überzeugung Wissen? Das fragt die Erkenntnistheorie."],"correctAnswer":"Erkenntnistheorie befasst sich mit der Frage, unter welchen Bedingungen eine wahre, gerechtfertigte Überzeugung als Wissen gelten kann."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Kommission befasste sich mit den Ursachen der ___.","options":["Krise","Katastrophe","Situation","Probleme"],"correctAnswer":"Krise"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He has been dealing with the history of the Middle Ages for years","wordBankItems":["Er","befasst","sich","seit","Jahren","mit","der","Geschichte","des","Mittelalters","."],"correctAnswer":"Er befasst sich seit Jahren mit der Geschichte des Mittelalters ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vorläufig'' means?","options":["provisional","temporary","preliminary","tentative"],"correctAnswer":"provisional"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000023f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss metaphysics at B2","Use Metaphysik vocabulary","Talk about being, identity, and causation"],"explanation":{"intro":"Metaphysics vocabulary covers the study of fundamental reality, being, identity, causation, and modality at B2.","culturalNote":"Metaphysik: literally beyond physics (Aristotle: ta meta ta physika). Key areas: Ontologie (ontology — what exists?), Kausalität (causation — what causes what?), Identität (identity — what makes X the same over time?), Modalität (modality — possibility, necessity). German contributions: Kant (limits of metaphysics — can''t know things-in-themselves), Hegel (Geist, dialectics), Heidegger (Sein und Zeit — Being and Time, Dasein, Seinsfrage). Analytic vs. Continental divide. Wiedergeburt der Metaphysik in analytic philosophy (David Lewis, possible worlds)."},"examples":[{"german":"Metaphysik stellt die grundlegendsten Fragen über die Struktur der Wirklichkeit, die weit über das hinausgehen, was empirische Wissenschaften beantworten können.","english":"Metaphysics poses the most fundamental questions about the structure of reality, which go far beyond what empirical sciences can answer."},{"german":"Kants Kritik der reinen Vernunft setzt der metaphysischen Spekulation Grenzen, indem sie zeigt, dass die menschliche Erkenntnis auf mögliche Erfahrung beschränkt ist.","english":"Kant''s Critique of Pure Reason sets limits to metaphysical speculation, by showing that human cognition is restricted to possible experience."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss metaphysics, ontology, and Kant''s limits on speculative reason at B2."}}',
'{"items":[{"word":"grundlegend","translation":"fundamental","pronunciation":"GROOND-lay-gend","example":"Grundlegende Fragen."},{"word":"die Wirklichkeit","translation":"reality","pronunciation":"dee VIRK-likh-kyt","example":"Struktur der Wirklichkeit."},{"word":"weit über X hinausgehen","translation":"to go far beyond X","pronunciation":"vyt ü-ber X hi-NOWS-gay-en","example":"Weit über das hinausgehen."},{"word":"die Spekulation","translation":"speculation","pronunciation":"dee shpeh-koo-lah-TSYOHN","example":"Metaphysische Spekulation."},{"word":"beschränkt","translation":"restricted/limited","pronunciation":"beh-SHRENKT","example":"Auf Erfahrung beschränkt."},{"word":"indem","translation":"by (doing), in that","pronunciation":"in-DAYM","example":"Indem sie zeigt, dass..."}]}',
'{"title":"Indem — by (doing), in that (states HOW something is achieved — the means or mechanism)","pattern":"indem + clause (verb last) = by doing X, in that (the indem-clause describes HOW the main action is accomplished)","explanation":"Indem + clause (subordinating conjunction, verb to end) = by doing, in that. Kant setzt Grenzen, indem er zeigt, dass... = Kant sets limits by showing that... The indem-clause describes the means or mechanism through which the main action is achieved. Compare: durch + Infinitiv (through — more nominal), dadurch dass (by the fact that — same meaning, slightly more formal), wobei (in the process of, whereby — introduces additional context rather than pure means).","examples":[{"sentence":"Er verbesserte sein Deutsch, indem er täglich Podcasts hörte.","translation":"He improved his German by listening to podcasts every day."},{"sentence":"Die Firma senkte Kosten, indem sie auf Homeoffice umstellte.","translation":"The company cut costs by switching to working from home."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Grundlegend'' means?","options":["fundamental","basic","primary","essential"],"correctAnswer":"fundamental"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Kant''s Critique of Pure Reason sets limits to metaphysical speculation, by showing that human cognition is restricted to possible experience.","options":["Kants Kritik der reinen Vernunft setzt der metaphysischen Spekulation Grenzen, indem sie zeigt, dass die menschliche Erkenntnis auf mögliche Erfahrung beschränkt ist.","Kant zeigte, dass Metaphysik keine Wissenschaft sein kann.","Für Kant ist menschliche Erkenntnis auf Erfahrung angewiesen.","Kant begrenzt die Metaphysik durch seine Erkenntnistheorie."],"correctAnswer":"Kants Kritik der reinen Vernunft setzt der metaphysischen Spekulation Grenzen, indem sie zeigt, dass die menschliche Erkenntnis auf mögliche Erfahrung beschränkt ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er verbesserte sein Deutsch, indem er täglich Podcasts ___.","options":["hörte","gehört hat","hört","angehört hat"],"correctAnswer":"hörte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The company cut costs by switching to working from home","wordBankItems":["Die","Firma","senkte","Kosten",",","indem","sie","auf","Homeoffice","umstellte","."],"correctAnswer":"Die Firma senkte Kosten , indem sie auf Homeoffice umstellte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Wirklichkeit'' means?","options":["reality","actuality","fact","existence"],"correctAnswer":"reality"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000240',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy of language at B2","Use Sprachphilosophie vocabulary","Talk about meaning, reference, and speech acts"],"explanation":{"intro":"Philosophy of language vocabulary covers meaning, reference, use, and speech acts at B2.","culturalNote":"Sprachphilosophie: key debates. Frege (Sinn und Bedeutung — sense and reference distinction). Russell (definite descriptions). Wittgenstein (early: Tractatus — language as picture of facts; late: Philosophische Untersuchungen — meaning as use, Sprachspiele/language games). Austin and Searle (Sprechakttheorie — speech act theory: locutionary, illocutionary, perlocutionary acts). Chomsky (Universalgrammatik — universal grammar, innateness). Sapir-Whorf Hypothese (language shapes thought)."},"examples":[{"german":"Wittgensteins späte Philosophie argumentiert, dass Bedeutung nicht in einem inneren mentalen Zustand liegt, sondern sich aus dem öffentlichen Gebrauch der Sprache in bestimmten Lebensformen ergibt.","english":"Wittgenstein''s late philosophy argues that meaning does not lie in an inner mental state, but arises from the public use of language in particular forms of life."},{"german":"Die Sprechakttheorie unterscheidet zwischen dem, was ein Satz bedeutet, und dem, was ein Sprecher damit tut — ob er informiert, verspricht, befiehlt oder warnt.","english":"Speech act theory distinguishes between what a sentence means and what a speaker does with it — whether they inform, promise, command, or warn."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss philosophy of language, Wittgenstein, and speech act theory at B2."}}',
'{"items":[{"word":"der Gebrauch","translation":"use/usage","pronunciation":"dayr geh-BROWKH","example":"Öffentlicher Gebrauch."},{"word":"die Lebensform","translation":"form of life","pronunciation":"dee LAY-bens-form","example":"Bestimmte Lebensformen."},{"word":"sich ergeben aus","translation":"to arise from/result from","pronunciation":"zikh er-GAY-ben ows","example":"Aus dem Gebrauch ergeben."},{"word":"der Sprecher","translation":"speaker","pronunciation":"dayr SHPREH-kher","example":"Was ein Sprecher tut."},{"word":"der Sprechakt","translation":"speech act","pronunciation":"dayr SHPREH-akt","example":"Sprechakttheorie."},{"word":"mental","translation":"mental","pronunciation":"men-TAHL","example":"Mentaler Zustand."}]}',
'{"title":"Sich aus etwas ergeben — to arise from, to result from (something follows logically/practically)","pattern":"etwas ergibt sich aus etwas = something arises from, results from, follows from (something — the result is produced by or follows from the source)","explanation":"Sich aus etwas ergeben = to arise from, to result from (something follows logically or practically from a source). Bedeutung ergibt sich aus dem Gebrauch = Meaning arises from use. Reflexive (ergibt sich, ergab sich, hat sich ergeben). Compare: entstehen aus (to arise from — more process-based), folgen aus (to follow from — more logical inference), resultieren aus (to result from — more causal), herrühren von (to stem from — source attribution).","examples":[{"sentence":"Aus dieser Analyse ergibt sich eine klare Empfehlung.","translation":"From this analysis, a clear recommendation arises."},{"sentence":"Die Konsequenzen ergeben sich logisch aus den Prämissen.","translation":"The consequences follow logically from the premises."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Gebrauch'' means?","options":["use/usage","application","employment","practice"],"correctAnswer":"use/usage"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Wittgenstein''s late philosophy argues that meaning does not lie in an inner mental state, but arises from the public use of language in particular forms of life.","options":["Wittgensteins späte Philosophie argumentiert, dass Bedeutung nicht in einem inneren mentalen Zustand liegt, sondern sich aus dem öffentlichen Gebrauch der Sprache in bestimmten Lebensformen ergibt.","Für den späten Wittgenstein ist Sprache ein öffentliches Phänomen.","Bedeutung entsteht durch den Gebrauch der Sprache in sozialen Kontexten.","Wittgenstein lehnte die Idee ab, dass Bedeutung in mentalen Zuständen liegt."],"correctAnswer":"Wittgensteins späte Philosophie argumentiert, dass Bedeutung nicht in einem inneren mentalen Zustand liegt, sondern sich aus dem öffentlichen Gebrauch der Sprache in bestimmten Lebensformen ergibt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Aus dieser Analyse ergibt sich eine klare ___.","options":["Empfehlung","Folgerung","Schlussfolgerung","Konklusion"],"correctAnswer":"Empfehlung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The consequences follow logically from the premises","wordBankItems":["Die","Konsequenzen","ergeben","sich","logisch","aus","den","Prämissen","."],"correctAnswer":"Die Konsequenzen ergeben sich logisch aus den Prämissen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Sprecher'' means?","options":["speaker","talker","narrator","spokesperson"],"correctAnswer":"speaker"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000241',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy of mind at B2","Use Philosophie des Geistes vocabulary","Talk about consciousness and the mind-body problem"],"explanation":{"intro":"Philosophy of mind vocabulary covers consciousness, the mind-body problem, and theories of mental states at B2.","culturalNote":"Philosophie des Geistes: central problem — Leib-Seele-Problem (mind-body problem). Positions: Substanzdualismus (substance dualism — Descartes: mind and body are distinct substances), Physikalismus/Materialismus (physicalism/materialism — mind is physical), Funktionalismus (functionalism — mental states are functional states), Phänomenales Bewusstsein (phenomenal consciousness — qualia, what it''s like to be X — Nagel: what is it like to be a bat?), Intentionalität (intentionality — Brentano: mental states are about something). Kognitionswissenschaft (cognitive science — interdisciplinary)."},"examples":[{"german":"Das schwere Problem des Bewusstseins besteht darin, zu erklären, warum und wie physische Gehirnprozesse zu subjektiven Erlebnissen — Qualia — führen.","english":"The hard problem of consciousness consists in explaining why and how physical brain processes give rise to subjective experiences — qualia."},{"german":"Der Funktionalismus definiert mentale Zustände durch ihre kausale Rolle innerhalb eines Systems, wodurch er die Möglichkeit offenlässt, dass auch nicht-biologische Systeme mentale Zustände haben können.","english":"Functionalism defines mental states through their causal role within a system, by which it leaves open the possibility that non-biological systems too can have mental states."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss philosophy of mind, the hard problem of consciousness, and functionalism at B2."}}',
'{"items":[{"word":"das Bewusstsein","translation":"consciousness","pronunciation":"dahs beh-VOOST-zyn","example":"Phänomenales Bewusstsein."},{"word":"das Erlebnis","translation":"experience","pronunciation":"dahs er-LAYP-nis","example":"Subjektives Erlebnis."},{"word":"die Qualia","translation":"qualia","pronunciation":"dee KVAH-lee-ah","example":"Qualia — subjektive Erlebnisse."},{"word":"offenlassen","translation":"to leave open","pronunciation":"OF-en-la-sen","example":"Eine Möglichkeit offenlassen."},{"word":"bestehen in","translation":"to consist in","pronunciation":"beh-SHTAY-en in","example":"Das Problem besteht darin."},{"word":"kausal","translation":"causal","pronunciation":"kow-ZAHL","example":"Kausale Rolle."}]}',
'{"title":"Bestehen in — to consist in (the essence or nature of something)","pattern":"etwas besteht in + dative (or darin, zu + infinitive) = something consists in, amounts to (defining the nature or core of something)","explanation":"Etwas besteht in etwas = something consists in (defining what X fundamentally is or amounts to). Das Problem besteht darin, zu erklären, warum... = The problem consists in explaining why... Darin zu + infinitive (darin = in this, followed by the activity). Compare: liegen in (to lie in — more spatial metaphor, similar meaning), ausmachen (to constitute — more casual), beinhalten (to involve/contain — listing components rather than defining essence).","examples":[{"sentence":"Die Herausforderung besteht darin, alle Interessen zu vereinen.","translation":"The challenge consists in uniting all interests."},{"sentence":"Der Kern des Problems besteht in mangelnder Kommunikation.","translation":"The core of the problem consists in a lack of communication."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Bewusstsein'' means?","options":["consciousness","awareness","mind","sentience"],"correctAnswer":"consciousness"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The hard problem of consciousness consists in explaining why and how physical brain processes give rise to subjective experiences — qualia.","options":["Das schwere Problem des Bewusstseins besteht darin, zu erklären, warum und wie physische Gehirnprozesse zu subjektiven Erlebnissen — Qualia — führen.","Das Bewusstseinsproblem ist eines der schwierigsten in der Philosophie.","Wie Gehirnprozesse Bewusstsein erzeugen, ist noch ungeklärt.","Qualia sind subjektive Erlebnisse, die durch Gehirnprozesse entstehen."],"correctAnswer":"Das schwere Problem des Bewusstseins besteht darin, zu erklären, warum und wie physische Gehirnprozesse zu subjektiven Erlebnissen — Qualia — führen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Herausforderung besteht darin, alle Interessen zu ___.","options":["vereinen","verbinden","zusammenführen","koordinieren"],"correctAnswer":"vereinen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The core of the problem consists in a lack of communication","wordBankItems":["Der","Kern","des","Problems","besteht","in","mangelnder","Kommunikation","."],"correctAnswer":"Der Kern des Problems besteht in mangelnder Kommunikation ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kausal'' means?","options":["causal","causative","cause-related","reason-based"],"correctAnswer":"causal"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000242',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social philosophy at B2","Use Sozialphilosophie vocabulary","Talk about community, identity, and solidarity"],"explanation":{"intro":"Social philosophy vocabulary covers community, social bonds, recognition, and solidarity at B2.","culturalNote":"Sozialphilosophie: questions about social life. Key themes: Gemeinschaft vs. Gesellschaft (Tönnies — community vs. association), Anerkennung (recognition — Hegel, Honneth: Kampf um Anerkennung — struggle for recognition), Solidarität (solidarity — Durkheim: mechanische vs. organische Solidarität — mechanical vs. organic solidarity), Soziales Kapital (social capital — Bourdieu, Putnam). German context: Habermas (communicative rationality, Lebensworld vs. Systemworld). Rawls vs. Communitarians (Walzer, Taylor)."},"examples":[{"german":"Axel Honneths Anerkennungstheorie argumentiert, dass das Streben nach Anerkennung in Liebe, Recht und Solidarität die grundlegende Triebfeder sozialer Kämpfe und moralischen Fortschritts ist.","english":"Axel Honneth''s recognition theory argues that the striving for recognition in love, law, and solidarity is the fundamental driving force of social struggles and moral progress."},{"german":"Ferdinand Tönnies unterschied zwischen Gemeinschaft — einem organischen, affektiven Zusammenleben — und Gesellschaft — einer rationalen, zweckgerichteten Assoziation freier Individuen.","english":"Ferdinand Tönnies distinguished between community — an organic, affective living-together — and society — a rational, purposeful association of free individuals."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss social philosophy, recognition theory, and Gemeinschaft vs. Gesellschaft at B2."}}',
'{"items":[{"word":"das Streben","translation":"striving/pursuit","pronunciation":"dahs SHTRAY-ben","example":"Streben nach Anerkennung."},{"word":"die Triebfeder","translation":"driving force/motivation","pronunciation":"dee TREEP-fay-der","example":"Grundlegende Triebfeder."},{"word":"die Anerkennung","translation":"recognition","pronunciation":"dee AN-er-ken-oong","example":"Kampf um Anerkennung."},{"word":"affektiv","translation":"affective","pronunciation":"a-fek-TEEF","example":"Affektives Zusammenleben."},{"word":"zweckgerichtet","translation":"purposeful/goal-directed","pronunciation":"TSVEK-geh-rikh-tet","example":"Zweckgerichtete Assoziation."},{"word":"die Assoziation","translation":"association","pronunciation":"dee as-so-tsya-TSYOHN","example":"Freie Assoziation."}]}',
'{"title":"Unterscheiden zwischen X und Y — to distinguish between X and Y","pattern":"jemand unterscheidet zwischen X und Y = someone distinguishes between X and Y (analytical distinction — separating two things that might be conflated)","explanation":"Zwischen X und Y unterscheiden = to distinguish between X and Y. Tönnies unterschied zwischen Gemeinschaft und Gesellschaft = Tönnies distinguished between community and society. Perfect: hat unterschieden. Compare: scharf trennen (to draw a sharp distinction — more emphatic separation), differenzieren zwischen (to differentiate between — often more technical), getrennt halten (to keep separate — ongoing act), abgrenzen (to demarcate — more spatial, setting boundaries).","examples":[{"sentence":"Man muss zwischen Symptomen und Ursachen unterscheiden.","translation":"One must distinguish between symptoms and causes."},{"sentence":"Die Studie unterscheidet zwischen kurz- und langfristigen Effekten.","translation":"The study distinguishes between short-term and long-term effects."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Triebfeder'' means?","options":["driving force/motivation","impulse","incentive","mainspring"],"correctAnswer":"driving force/motivation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Axel Honneth''s recognition theory argues that the striving for recognition in love, law, and solidarity is the fundamental driving force of social struggles and moral progress.","options":["Axel Honneths Anerkennungstheorie argumentiert, dass das Streben nach Anerkennung in Liebe, Recht und Solidarität die grundlegende Triebfeder sozialer Kämpfe und moralischen Fortschritts ist.","Honneth sieht Anerkennungskämpfe als Motor des moralischen Fortschritts.","Soziale Kämpfe entstehen aus dem Bedürfnis nach Anerkennung.","Für Honneth streben Menschen nach Anerkennung in sozialen Beziehungen."],"correctAnswer":"Axel Honneths Anerkennungstheorie argumentiert, dass das Streben nach Anerkennung in Liebe, Recht und Solidarität die grundlegende Triebfeder sozialer Kämpfe und moralischen Fortschritts ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Man muss zwischen Symptomen und Ursachen ___.","options":["unterscheiden","trennen","differenzieren","abgrenzen"],"correctAnswer":"unterscheiden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The study distinguishes between short-term and long-term effects","wordBankItems":["Die","Studie","unterscheidet","zwischen","kurz-","und","langfristigen","Effekten","."],"correctAnswer":"Die Studie unterscheidet zwischen kurz- und langfristigen Effekten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zweckgerichtet'' means?","options":["purposeful/goal-directed","intentional","deliberate","targeted"],"correctAnswer":"purposeful/goal-directed"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000243',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Critical Theory at B2","Use Kritische Theorie vocabulary","Talk about the Frankfurt School"],"explanation":{"intro":"Critical Theory vocabulary covers the Frankfurt School''s interdisciplinary critique of modernity, capitalism, and culture at B2.","culturalNote":"Kritische Theorie: Frankfurter Schule (Frankfurt School). Founded ~1923 (Institut für Sozialforschung). Key figures: Horkheimer, Adorno (Dialektik der Aufklärung — Dialectic of Enlightenment, 1944 — Enlightenment becomes its own opposite: domination), Benjamin (Kunstwerk im Zeitalter der Reproduktion — the aura of art), Marcuse (eindimensionaler Mensch — one-dimensional man), Habermas (communicative action, public sphere — Öffentlichkeit). Key concepts: Entfremdung (alienation), Ideologiekritik (ideology critique), Warencharakter (commodity character), Kulturindustrie (culture industry — mass culture as social control)."},"examples":[{"german":"Die Frankfurter Schule wandte marxistische Kategorien kritisch auf Phänomene an, die Marx selbst nicht vorhergesehen hatte — Massenmedien, Konsumgesellschaft und technische Rationalität.","english":"The Frankfurt School critically applied Marxist categories to phenomena that Marx himself had not foreseen — mass media, consumer society, and technical rationality."},{"german":"Adorno und Horkheimers These, dass Aufklärung in Mythos umschlägt, wenn sie sich in ein blosses Instrument der Naturbeherrschung verwandelt, bleibt ein provokanter Einwand gegen naiven Fortschrittsoptimismus.","english":"Adorno and Horkheimer''s thesis that Enlightenment turns into myth when it transforms itself into a mere instrument of the domination of nature remains a provocative objection against naive optimism about progress."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Critical Theory, the Frankfurt School, and the dialectic of Enlightenment at B2."}}',
'{"items":[{"word":"anwenden auf","translation":"to apply to","pronunciation":"AN-ven-den owf","example":"Auf Phänomene anwenden."},{"word":"vorhersehen","translation":"to foresee","pronunciation":"FOR-hayr-zay-en","example":"Nicht vorhergesehen."},{"word":"umschlagen in","translation":"to turn into/flip into","pronunciation":"OOM-shlag-en in","example":"In Mythos umschlagen."},{"word":"das Instrument","translation":"instrument","pronunciation":"dahs in-stru-MENT","example":"Bloßes Instrument."},{"word":"die Naturbeherrschung","translation":"domination of nature","pronunciation":"dee nah-TOOR-beh-her-shoong","example":"Naturbeherrschung."},{"word":"provokant","translation":"provocative","pronunciation":"pro-vo-KANT","example":"Provokanter Einwand."}]}',
'{"title":"In etwas umschlagen — to turn into, to flip into (a dramatic reversal)","pattern":"etwas schlägt in etwas um = something turns into something else (umschlagen = flip, sudden reversal — often dramatic or paradoxical)","explanation":"In etwas umschlagen = to turn into, to flip into (separable: schlägt...um, schlug...um, ist...umgeschlagen — sein, because change of state). Aufklärung schlägt in Mythos um = Enlightenment turns into myth (dramatic reversal — the thing becomes its opposite). Used for unexpected or paradoxical reversals. Compare: sich verwandeln in (to transform into — more gradual, less sudden), sich in X verkehren (to reverse into X — more deliberate antithesis), kippen in (to tip/flip into — more colloquial).","examples":[{"sentence":"Die anfängliche Begeisterung schlug in Frustration um.","translation":"The initial enthusiasm turned into frustration."},{"sentence":"Vertrauen kann schnell in Misstrauen umschlagen.","translation":"Trust can quickly turn into distrust."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Provokant'' means?","options":["provocative","challenging","contentious","confrontational"],"correctAnswer":"provocative"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Frankfurt School critically applied Marxist categories to phenomena that Marx himself had not foreseen — mass media, consumer society, and technical rationality.","options":["Die Frankfurter Schule wandte marxistische Kategorien kritisch auf Phänomene an, die Marx selbst nicht vorhergesehen hatte — Massenmedien, Konsumgesellschaft und technische Rationalität.","Die Frankfurter Schule entwickelte den Marxismus für das 20. Jahrhundert weiter.","Horkheimer und Adorno analysierten Massenmedien aus marxistischer Perspektive.","Die Frankfurter Schule kritisierte Phänomene, die im klassischen Marxismus keine Rolle spielten."],"correctAnswer":"Die Frankfurter Schule wandte marxistische Kategorien kritisch auf Phänomene an, die Marx selbst nicht vorhergesehen hatte — Massenmedien, Konsumgesellschaft und technische Rationalität."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die anfängliche Begeisterung schlug in Frustration ___.","options":["um","ab","über","durch"],"correctAnswer":"um"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Trust can quickly turn into distrust","wordBankItems":["Vertrauen","kann","schnell","in","Misstrauen","umschlagen","."],"correctAnswer":"Vertrauen kann schnell in Misstrauen umschlagen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anwenden auf'' means?","options":["to apply to","to use for","to employ for","to put to use"],"correctAnswer":"to apply to"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000244',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss postmodernism at B2","Use Postmoderne vocabulary","Talk about grand narratives and relativism"],"explanation":{"intro":"Postmodernism vocabulary covers the critique of grand narratives, the deconstruction of truth, and key postmodern thinkers at B2.","culturalNote":"Postmoderne: Lyotard (La condition postmoderne 1979 — Ende der großen Erzählungen/end of grand narratives), Derrida (Dekonstruktion — deconstruction, différance), Foucault (Diskursanalyse — discourse analysis, power/knowledge nexus: Macht-Wissen). Key concept: große Erzählungen (grand narratives — Marxism, Enlightenment, Christianity — no longer provide universal legitimation). Key debates: Relativismus (relativism — is all truth relative?), Habermas''s critique of postmodernism as neoconservative (loses rational critique)."},"examples":[{"german":"Lyotards Begriff der Postmoderne bezeichnet eine Skepsis gegenüber allen übergreifenden Legitimationserzählungen, die beanspruchen, universelle Wahrheiten zu begründen.","english":"Lyotard''s concept of postmodernism denotes a scepticism towards all overarching narratives of legitimation that claim to ground universal truths."},{"german":"Foucaults genealogische Methode analysiert, wie Wissens- und Wahrheitsregimes in historisch spezifischen Machtkonstellationen entstehen und was sie in dem Moment ausschließen, in dem sie etwas als Wahrheit etablieren.","english":"Foucault''s genealogical method analyses how regimes of knowledge and truth arise in historically specific constellations of power and what they exclude at the moment they establish something as truth."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss postmodernism, Lyotard, Foucault, and the critique of grand narratives at B2."}}',
'{"items":[{"word":"bezeichnen","translation":"to denote/designate","pronunciation":"beh-TSYKH-nen","example":"Einen Begriff bezeichnen."},{"word":"übergreifend","translation":"overarching/spanning","pronunciation":"ü-ber-GRY-fend","example":"Übergreifende Erzählung."},{"word":"die Legitimationserzählung","translation":"narrative of legitimation","pronunciation":"dee leh-gi-ti-mah-TSYOHNS-er-tsä-loong","example":"Legitimationserzählung."},{"word":"beanspruchen","translation":"to claim","pronunciation":"beh-AN-shproo-khen","example":"Universelle Wahrheit beanspruchen."},{"word":"genealogisch","translation":"genealogical","pronunciation":"geh-neh-ah-LO-gish","example":"Genealogische Methode."},{"word":"ausschließen","translation":"to exclude","pronunciation":"OWS-shlee-sen","example":"Was sie ausschließen."}]}',
'{"title":"In dem Moment, in dem — at the moment when (simultaneous action)","pattern":"in dem Moment, in dem + clause = at the moment when (relative clause with in dem to specify the exact simultaneous moment)","explanation":"In dem Moment, in dem + clause = at the very moment when (specifically, the exact point in time — not ''when'' in general, but the precise moment). Foucault analysiert, was Wahrheitsregimes ausschließen, in dem Moment, in dem sie etwas als Wahrheit etablieren = ...at the moment they establish something as truth. Double in dem construction: in dem Moment (prepositional phrase) + in dem (relative pronoun in dative after in). Compare: als (when — simple past simultaneous), wenn (whenever/when — conditional or repeated), sobald (as soon as — immediately after), gleichzeitig (simultaneously — adverb, not conjunction).","examples":[{"sentence":"In dem Moment, in dem sie ankam, begann das Konzert.","translation":"At the very moment when she arrived, the concert began."},{"sentence":"Der Effekt tritt in dem Moment ein, in dem die Temperatur 100°C erreicht.","translation":"The effect occurs at the moment when the temperature reaches 100°C."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Übergreifend'' means?","options":["overarching/spanning","comprehensive","all-encompassing","universal"],"correctAnswer":"overarching/spanning"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Lyotard''s concept of postmodernism denotes a scepticism towards all overarching narratives of legitimation that claim to ground universal truths.","options":["Lyotards Begriff der Postmoderne bezeichnet eine Skepsis gegenüber allen übergreifenden Legitimationserzählungen, die beanspruchen, universelle Wahrheiten zu begründen.","Lyotard kritisierte alle großen Erzählungen als überholt.","Postmoderne bedeutet Skepsis gegenüber universellen Wahrheitsansprüchen.","Für Lyotard sind große Erzählungen nicht mehr glaubwürdig."],"correctAnswer":"Lyotards Begriff der Postmoderne bezeichnet eine Skepsis gegenüber allen übergreifenden Legitimationserzählungen, die beanspruchen, universelle Wahrheiten zu begründen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"In dem Moment, in dem sie ankam, begann das ___.","options":["Konzert","Treffen","Gespräch","Programm"],"correctAnswer":"Konzert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The effect occurs at the moment when the temperature reaches 100 degrees","wordBankItems":["Der","Effekt","tritt","in","dem","Moment","ein",",","in","dem","die","Temperatur","100°C","erreicht","."],"correctAnswer":"Der Effekt tritt in dem Moment ein , in dem die Temperatur 100°C erreicht ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Beanspruchen'' means?","options":["to claim","to assert","to demand","to require"],"correctAnswer":"to claim"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

